#nullable enable // autogenerated

using MVZ2.GameContent.Buffs.Contraptions;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Entities;
using MVZ2Logic.Level;
using PVZEngine.Buffs;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Models;
using PVZEngine.Timing;

namespace MVZ2.GameContent.Contraptions
{
    /// <summary>
    /// 高频脉冲发射器：固定节奏单发（普通 0.3 秒/发，升级后 0.1 秒/发），
    /// 每次发射有 5% 概率卡壳，卡壳后陷入 1.5 秒短路（黑客骇入同款特效），
    /// 短路结束后自动继续发射。
    /// </summary>
    [AutoEntityBehaviourDefinition(VanillaContraptionNames.hfpd)]
    public class HighFrequencyPulseDispenser : DispenserFamily
    {
        public HighFrequencyPulseDispenser(string nsp, string name) : base(nsp, name)
        {
        }

        public override void Init(Entity entity)
        {
            base.Init(entity);
            InitShootTimer(entity);
        }
        protected override void UpdateAI(Entity entity)
        {
            base.UpdateAI(entity);
            // 固定节奏单发：射击计时到点且有目标时打一发（基类 ShootTick 已处理）
            ShootTick(entity);
        }
        protected override void UpdateLogic(Entity entity)
        {
            base.UpdateLogic(entity);
            // 把状态交给动画系统：是否升级、是否用交替枪管
            entity.SetModelProperty("Upgraded", IsUpgraded(entity));
            entity.SetModelProperty("GatlinAlt", IsGatlinAlt(entity));
        }
        public override Entity? Shoot(Entity entity)
        {
            // 每发一次就切换枪管状态，做出左右交替开火的效果
            SetGatlinAlt(entity, !IsGatlinAlt(entity));
            var result = base.Shoot(entity);
            // 每次发射有 5% 概率卡壳：
            // 陷入 1.5 秒短路（AI 冻结 + 冒火花特效，黑客骇入同款），到期自动恢复射击
            if (result != null && entity.RNG.Next(100) < JAM_CHANCE_PERCENT)
            {
                entity.ShortCircuit(Ticks.FromSeconds(JAM_SHORT_CIRCUIT_SECONDS), null);
            }
            return result;
        }
        public override bool CanEvoke(Entity entity)
        {
            // 已经升级过就不能再放大招
            if (IsUpgraded(entity))
                return false;
            return base.CanEvoke(entity);
        }
        protected override void OnEvoke(Entity entity)
        {
            base.OnEvoke(entity);
            // 大招：永久升级，射速从 0.3 秒/发提升到 0.1 秒/发（同时保留发光效果）
            entity.AddBuff<HFPDUpgradedBuff>();
            entity.PlaySound(VanillaSoundID.gunReload);
            entity.PlaySound(VanillaSoundID.powerUp);
            entity.PlaySound(VanillaSoundID.motor);
        }
        // 射击间隔（游戏逻辑 30 tick/秒）。
        // 基类 ShootTick 每次到期都会用这个值重置计时器，
        // 所以升级的当刻起，下一发就按新射速走，不用额外处理。
        protected override int GetTimerTime(Entity entity)
        {
            if (entity.Level.IsIZombie())
                return ATTACK_INTERVAL_IZOMBIE; // 我僵尸模式沿用原版的慢速间隔
            return IsUpgraded(entity) ? SHOOT_INTERVAL_TICKS_UPGRADED : SHOOT_INTERVAL_TICKS;
        }
        public static bool IsGatlinAlt(Entity entity) => entity.GetBehaviourField<bool>(PROP_GATLIN_ALT);
        public static void SetGatlinAlt(Entity entity, bool value) => entity.SetBehaviourField(PROP_GATLIN_ALT, value);
        public static bool IsUpgraded(Entity entity) => entity.HasBuff<HFPDUpgradedBuff>();

        public const int SHOOT_INTERVAL_TICKS = 9;            // 射击间隔：9 tick = 0.3 秒
        public const int SHOOT_INTERVAL_TICKS_UPGRADED = 3;   // 升级后：3 tick = 0.1 秒
        public const int JAM_CHANCE_PERCENT = 5;              // 每次发射的卡壳概率（%）
        public const float JAM_SHORT_CIRCUIT_SECONDS = 1.5f;  // 卡壳后的短路时长（秒）
        private const int ATTACK_INTERVAL_IZOMBIE = 45;       // 我僵尸模式的射击间隔（与原版基类一致）
        public static readonly VanillaEntityPropertyMeta<bool> PROP_GATLIN_ALT = new VanillaEntityPropertyMeta<bool>("gatlin_alt");
    }
}
